1	/**
2	 * Builds the whole washer world in absolute coordinates around the master course.
3	 * Drum A (01–02) → chute → whirlpool basin room (03) → gold ring pipe (04) → perforated current tube
4	 * (05) → arch hall (06) → washer tube + deep plunge (07) → Final Spin Chamber (08–11).
5	 */
6	import * as THREE from 'three';
7	import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
8	import { Course, WORLD, funnelY } from './course';
9	import { perforatedMetal, gold, goldRibbed, chrome, glass, painted, canvasTexture, washerTubeEnv, withFarGlow, type FarGlow } from './materials';
10	import { buildTubeGeometry, buildRings, buildWallLids, courseTubePath, straightTubePath, tubeCenterAt } from './tube';
11	import { buildLaundryRoom, LaundryRoom } from './laundryRoom';
12	import { buildTowel, TowelMesh } from './towel';
13	
14	export interface Environment {
15	  group: THREE.Group;
16	  update(time: number, dt: number): void;
17	  doorA: THREE.Object3D; // hinge pivot (rotation.y opens)
18	  doorC: THREE.Object3D;
19	  roomA: LaundryRoom & { anchor: THREE.Object3D };
20	  roomC: LaundryRoom & { anchor: THREE.Object3D };
21	  towel: TowelMesh; // on the chamber platform (08–11)
22	  drumTowel: TowelMesh; // bundle wrapped around Benny in drum A (01–02)
23	  laundry: { sock: THREE.Object3D; shirt: THREE.Object3D };
24	  /** groups toggled per scene for performance */
25	  zones: Record<'drumA' | 'basin' | 'tubes' | 'chamber', THREE.Group>;
26	  /** straight 05–07 tunnel axis (camera alignment) */
27	  tubeAxis: { path: import('./tube').TubePath; s0: number; s1: number };
28	}
29	
30	const sm = (a: number, b: number, x: number) => {
31	  const t = THREE.MathUtils.clamp((x - a) / (b - a), 0, 1);
32	  return t * t * (3 - 2 * t);
33	};
34	
35	export function buildEnvironment(course: Course): Environment {
36	  const root = new THREE.Group();
37	  root.name = 'washer_world';
38	  const zones = {
39	    drumA: new THREE.Group(),
40	    basin: new THREE.Group(),
41	    tubes: new THREE.Group(),
42	    chamber: new THREE.Group(),
43	  };
44	  Object.entries(zones).forEach(([k, g]) => { g.name = 'zone_' + k; root.add(g); });
45	  const goldMat = gold();
46	  const goldSoft = gold({ roughness: 0.3, emissive: 0.3 });
47	  const chromeMat = chrome();
48	  const animated: ((t: number, dt: number) => void)[] = [];
49	
50	  // =====================================================================================
51	  // Drum A (01–02)
52	  // =====================================================================================
53	  const dA = WORLD.drumA;
54	  const drumLen = dA.zDoor - dA.zBack;
55	  const drumGeo = new THREE.CylinderGeometry(dA.radius, dA.radius, drumLen, 96, 24, true);
56	  drumGeo.rotateX(Math.PI / 2);
57	  drumGeo.translate(0, 0, (dA.zDoor + dA.zBack) / 2);
58	  const drumMat = perforatedMetal({ color: '#f04fc8', emissive: '#c22aa6', emissiveIntensity: 0.3, slot: 0, repeatU: 54, repeatV: 15, holeSize: 0.44, streaks: 0.15 });
59	  zones.drumA.add(new THREE.Mesh(drumGeo, drumMat));
60	  // back wall with the drain opening
61	  const backShape = new THREE.Shape();
62	  backShape.absarc(0, 0, dA.radius, 0, Math.PI * 2, false);
63	  const drainHole = new THREE.Path();
64	  drainHole.absarc(-0.3, -3.05, 1.85, 0, Math.PI * 2, true);
65	  backShape.holes.push(drainHole);
66	  const backGeo = new THREE.ShapeGeometry(backShape, 48);
67	  backGeo.translate(0, 0, dA.zBack);
68	  const backMat = perforatedMetal({ color: '#e544c4', slot: 0, repeatU: 9, repeatV: 9, holeSize: 0.4, side: THREE.DoubleSide, streaks: 0 });
69	  zones.drumA.add(new THREE.Mesh(backGeo, backMat));
70	  // front wall annulus
71	  const frontShape = new THREE.Shape();
72	  frontShape.absarc(0, 0, dA.radius, 0, Math.PI * 2, false);
73	  const doorHole = new THREE.Path();
74	  doorHole.absarc(0, 0, dA.doorRadius, 0, Math.PI * 2, true);
75	  frontShape.holes.push(doorHole);
76	  const frontGeo = new THREE.ShapeGeometry(frontShape, 64);
77	  frontGeo.translate(0, 0, dA.zDoor);
78	  zones.drumA.add(new THREE.Mesh(frontGeo, perforatedMetal({ color: '#f15ccd', slot: 0, repeatU: 8, repeatV: 8, holeSize: 0.0, side: THREE.DoubleSide, streaks: 0, metalness: 0.85, roughness: 0.18 })));
79	  // gold door ring (thick) + chrome inner lip
80	  const ringA = new THREE.Mesh(new THREE.TorusGeometry(dA.doorRadius + 0.35, 0.48, 24, 96), goldMat);
81	  ringA.position.set(0, 0, dA.zDoor - 0.1);
82	  zones.drumA.add(ringA);
83	  const ringA2 = new THREE.Mesh(new THREE.TorusGeometry(dA.doorRadius + 1.15, 0.22, 16, 96), goldSoft);
84	  ringA2.position.set(0, 0, dA.zDoor - 0.15);
85	  zones.drumA.add(ringA2);
86	  // lifters (gold baffles)
87	  for (const ang of [52, 128, 270]) {
88	    const a = THREE.MathUtils.degToRad(ang);
89	    const lifter = new THREE.Mesh(new RoundedBoxGeometry(1.5, 1.1, drumLen - 1.6, 4, 0.5), goldMat);
90	    lifter.position.set(Math.cos(a) * (dA.radius - 0.45), Math.sin(a) * (dA.radius - 0.45), (dA.zDoor + dA.zBack) / 2 - 0.3);
91	    lifter.rotation.z = a + Math.PI / 2;
92	    zones.drumA.add(lifter);
93	  }
94	  // washer door A (hinged on the left seen from the room: pivot at x=-r)
95	  const doorA = new THREE.Group();
96	  doorA.name = 'doorA_pivot';
97	  doorA.position.set(-(dA.doorRadius + 0.6), 0, dA.zDoor + 0.55);
98	  const doorAInner = new THREE.Group();
99	  doorAInner.position.set(dA.doorRadius + 0.6, 0, 0);
100	  const doorRingA = new THREE.Mesh(new THREE.TorusGeometry(dA.doorRadius + 0.2, 0.42, 20, 80), chromeMat);
101	  const doorGlassA = new THREE.Mesh(new THREE.CircleGeometry(dA.doorRadius + 0.05, 48), glass('#e8f0ff', 0.1));
102	  doorAInner.add(doorRingA, doorGlassA);
103	  doorA.add(doorAInner);
104	  zones.drumA.add(doorA);
105	  // laundry room A outside the door
106	  const roomA = buildLaundryRoom({ floorDrop: 11, palette: 'warm' });
107	  const anchorA = new THREE.Group();
108	  anchorA.position.set(0, 0, dA.zDoor + 0.8);
109	  anchorA.add(roomA.group);
110	  zones.drumA.add(anchorA);
111	  // floating laundry: blue striped sock + pink star T-shirt
112	  const sock = buildSock();
113	  const shirt = buildShirt();
114	  zones.drumA.add(sock, shirt);
115	  // towel bundle around Benny
116	  const drumTowel = buildTowel();
117	  drumTowel.setBundle(1);
118	  zones.drumA.add(drumTowel.mesh);
119	  // chute from drum A drain to the basin rim
120	  // the chute begins exactly where the course passes through the drum's back wall
121	  let sChute0 = course.marks['02_drain'] - 3;
122	  while (course.sample(sChute0).pos.z > dA.zBack + 0.3 && sChute0 < course.stage('03').s0) sChute0 += 0.1;
123	  const sChute1 = course.stage('03').s0 + 0.3;
124	  const chutePath = courseTubePath(course, () => 2.25, 0.55);
125	  const chute = new THREE.Mesh(
126	    buildTubeGeometry(chutePath, sChute0, sChute1, { radial: 36, step: 0.5, vScale: 1 }),
127	    perforatedMetal({ color: '#e94ad0', slot: 0, repeatU: 22, repeatV: 1.6, holeSize: 0.38 }),
128	  );
129	  zones.drumA.add(chute);
130	  zones.drumA.add(buildRings(chutePath, sChute0 + 1.5, sChute1 - 1, 3.2, goldMat, { tube: 0.09 }));
131	
132	  // =====================================================================================
133	  // Whirlpool basin room (03) + backdrop shared with 04
134	  // =====================================================================================
135	  const B = WORLD.basin;
136	  const prof: THREE.Vector2[] = [];
137	  for (let i = 0; i <= 40; i++) {
138	    const r = B.drainRadius * 1.04 + (B.rimRadius + 0.4 - B.drainRadius * 1.04) * (i / 40);
139	    prof.push(new THREE.Vector2(r, funnelY(r) - 0.45));
140	  }
141	  const funnelGeo = new THREE.LatheGeometry(prof, 96);
142	  funnelGeo.translate(B.center.x, 0, B.center.z);
143	  zones.basin.add(new THREE.Mesh(funnelGeo, perforatedMetal({ color: '#e04fd0', slot: 0, repeatU: 60, repeatV: 22, holeSize: 0.3, side: THREE.DoubleSide, streaks: 0 })));
144	  // thick gold drain lip + inner ring (ref 03: concentric gold rings inside the drain)
145	  for (const [rr, tt, dy] of [[B.drainRadius + 0.15, 0.42, 0.1], [B.drainRadius - 0.55, 0.22, -0.9]] as const) {
146	    const lip = new THREE.Mesh(new THREE.TorusGeometry(rr, tt, 18, 96), goldMat);
147	    lip.rotation.x = Math.PI / 2;
148	    lip.position.set(B.center.x, funnelY(B.drainRadius) + dy, B.center.z);
149	    zones.basin.add(lip);
150	  }
151	  const rim = new THREE.Mesh(new THREE.TorusGeometry(B.rimRadius + 0.5, 0.75, 24, 128), goldMat);
152	  rim.rotation.x = Math.PI / 2;
153	  rim.position.set(B.center.x, B.rimY + 0.25, B.center.z);
154	  zones.basin.add(rim);
155	  const rim2 = new THREE.Mesh(new THREE.TorusGeometry(B.rimRadius + 2.1, 0.35, 16, 128), goldSoft);
156	  rim2.rotation.x = Math.PI / 2;
157	  rim2.position.set(B.center.x, B.rimY + 0.35, B.center.z);
158	  zones.basin.add(rim2);
159	  // glossy pink deck around the basin
160	  const deckShape = new THREE.Shape();
161	  deckShape.moveTo(-34, -34); deckShape.lineTo(34, -34); deckShape.lineTo(34, 30); deckShape.lineTo(-34, 30); deckShape.lineTo(-34, -34);
162	  const deckHole = new THREE.Path();
163	  deckHole.absarc(0, 0, B.rimRadius + 0.4, 0, Math.PI * 2, true);
164	  deckShape.holes.push(deckHole);
165	  const deck = new THREE.Mesh(new THREE.ShapeGeometry(deckShape, 64), new THREE.MeshStandardMaterial({ color: '#f36fd6', metalness: 0.5, roughness: 0.2, emissive: '#c43bb0', emissiveIntensity: 0.35, side: THREE.DoubleSide }));
166	  deck.rotation.x = -Math.PI / 2;
167	  deck.position.set(B.center.x, B.rimY + 0.3, B.center.z);
168	  zones.basin.add(deck);
169	  buildBasinBackdrop(zones.basin, goldMat, chromeMat);
170	
171	  // =====================================================================================
172	  // 04 gold ring pipe
173	  // =====================================================================================
174	  const s04 = course.stage('04').s0, s05 = course.stage('05').s0;
175	  const tubeR = (s: number) => course.prop('tube', s);
176	  // the pipe mouth is the drain hole itself: narrow at the lip, opening up as it dives
177	  // the ring tunnel starts just ahead of Benny on the open slide (ref 04), with a flared mouth
178	  const g0 = s04 + 5.0;
179	  const r04 = (s: number) => tubeR(s) + 1.8 * (1 - sm(g0, g0 + 6, s));
180	  const goldPath = courseTubePath(course, r04, 0.9);
181	  const goldPipe = new THREE.Mesh(buildTubeGeometry(goldPath, g0, s05, { radial: 56, step: 0.4 }), goldRibbed(1.25));
182	  zones.tubes.add(goldPipe);
183	  zones.tubes.add(buildRings(goldPath, g0 + 0.2, s05 - 1, 1.6, goldMat, { tube: 0.05, inset: 0.02 }));
184	  // big mouth rings at the drain
185	  for (let i = 0; i < 4; i++) {
186	    const s = g0 + 0.05 + i * 0.3;
187	    zones.tubes.add(buildRings(goldPath, s, s + 0.01, 1, goldMat, { tube: 0.07, extra: 0.4 + i * 0.22 }));
188	  }
189	
190	  // =====================================================================================
191	  // 05–07 perforated tubes (incl. the 06 arch hall and the full 07 plunge)
192	  // =====================================================================================
193	  const s08 = course.stage('08').s0;
194	  const pinkFlow = pinkFlowMaterial();
195	  // refs 05–07: rich saturated magenta→violet glossy pressed metal, dense glowing slot rows, warm light
196	  // far down the tunnel. Own reflection environment (no cyan studio panel) + correct inward normals.
197	  // hot magenta near → violet mid-tunnel → warm yellow-white core at the vanishing point
198	  const tubeGlow: FarGlow = { color: '#ffd08a', near: 48, far: 105, strength: 1.5 };
199	  const wallGlow: FarGlow = { ...tubeGlow, mid: { color: '#8a3cf0', near: 10, far: 42, amount: 0.55 } };
200	  const tubeEnv = washerTubeEnv('wall');
201	  const goldEnv = washerTubeEnv('gold');
202	  const perfTubeMat = perforatedMetal({
203	    color: '#f24bd6', emissive: '#4a0866', emissiveIntensity: 0.32, holeColor: '#14001f',
204	    slot: 1, repeatU: 42, repeatV: 0.8, holeSize: 0.62, streaks: 0.15, metalness: 0.9, roughness: 0.22,
205	    relief: { corrugation: 0.035, bevel: 0.06, bevelWidth: 0.1 }, rimColor: '#ff6fe6', rimStrength: 0.8,
206	    envMap: tubeEnv, envMapIntensity: 0.78, farGlow: wallGlow,
207	  });
208	  // straight-axis tunnel (05 → 07 incl. arch + plunge); the stream winds inside it
209	  const perfPath = straightTubePath(course, s05, s08, { window: 30, taper: 14, baseRadius: tubeR });
210	  const chunk = 40;
211	  for (let a = s05; a < s08; a += chunk) {
212	    const b = Math.min(s08 + 0.0, a + chunk + 0.6);
213	    zones.tubes.add(new THREE.Mesh(buildTubeGeometry(perfPath, a, b, { radial: 72, step: 0.6, frontNormals: true }), perfTubeMat));
214	    // glossy magenta flow sheet lining the tube floor under the stream (refs 05/07 pink banks)
215	    zones.tubes.add(new THREE.Mesh(buildTubeGeometry(perfPath, a, b, { radial: 24, step: 0.8, arc: 1.9, inset: -0.12, vScale: 6, frontNormals: true }), pinkFlow.material));
216	  }
217	  // thick polished orange-gold ring collars at even spacing (refs 05–07: ~8–10 converging rings)
218	  const ringMat = withFarGlow(gold({ color: '#ffc04d', roughness: 0.14, emissive: 0.22 }), tubeGlow, 'ring');
219	  ringMat.envMap = goldEnv;
220	  ringMat.envMapIntensity = 1.3;
221	  const ringSpacing = 7.2;
222	  // gold junction collar 04→05 (slightly heavier)
223	  zones.tubes.add(buildRings(perfPath, s05 + 0.3, s05 + 0.31, 1, ringMat, { inset: 0.02, collar: { depth: 0.075, lip: 0.02, width: 1.3 } }));
224	  zones.tubes.add(buildRings(perfPath, s05 + 3, s08 - 1, ringSpacing, ringMat, { inset: 0.02, collar: { depth: 0.062, lip: 0.016, width: 1.0 } }));
225	  // wall lids: one pair of polished copper-gold caps per ring bay on the upper side walls
226	  const lidMat = withFarGlow(gold({ color: '#ffa65a', roughness: 0.18, emissive: 0.25 }), tubeGlow, 'lid');
227	  lidMat.envMap = goldEnv;
228	  lidMat.envMapIntensity = 1.25;
229	  zones.tubes.add(buildWallLids(perfPath, s05 + 3 + ringSpacing * 0.5, s08 - 6, ringSpacing, lidMat, { angleDeg: 20, size: 1.15, height: 0.42, down: 0.7, sink: 0.3 }));
230	  animated.push(pinkFlow.update);
231	
232	  // =====================================================================================
233	  // Final Spin Chamber (08–11)
234	  // =====================================================================================
235	  const C = WORLD.chamber;
236	  const cLen = C.zBack - C.zDoor;
237	  const chamberGeo = new THREE.CylinderGeometry(C.radius, C.radius, cLen, 120, 30, true);
238	  chamberGeo.rotateX(Math.PI / 2);
239	  chamberGeo.translate(C.center.x, C.center.y, (C.zBack + C.zDoor) / 2);
240	  const chamberMat = perforatedMetal({ color: '#cf45dc', emissive: '#9a24b8', emissiveIntensity: 0.3, slot: 1, repeatU: 92, repeatV: 22, holeSize: 0.46, streaks: 0.45 });
241	  zones.chamber.add(new THREE.Mesh(chamberGeo, chamberMat));
242	  // back wall with the 07 inlet hole
243	  const inletC = tubeCenterAt(perfPath, s08 - 0.05);
244	  const inletR = perfPath.radius(s08 - 0.05);
245	  const cb = new THREE.Shape();
246	  cb.absarc(C.center.x, C.center.y, C.radius, 0, Math.PI * 2, false);
247	  const inHole = new THREE.Path();
248	  inHole.absarc(inletC.x, Math.max(inletC.y, C.center.y - C.radius + inletR + 0.15), inletR - 0.05, 0, Math.PI * 2, true);
249	  cb.holes.push(inHole);
250	  const cbGeo = new THREE.ShapeGeometry(cb, 64);
251	  cbGeo.translate(0, 0, C.zBack);
252	  zones.chamber.add(new THREE.Mesh(cbGeo, perforatedMetal({ color: '#cf45dc', slot: 1, repeatU: 12, repeatV: 12, holeSize: 0.4, side: THREE.DoubleSide })));
253	  for (const [rr, tt, dz] of [[inletR + 0.35, 0.85, -0.3], [inletR + 1.7, 0.4, -0.2], [inletR + 2.6, 0.25, -0.1]] as const) {
254	    const ring = new THREE.Mesh(new THREE.TorusGeometry(rr, tt, 24, 120), goldMat);
255	    ring.position.set(inletC.x, inletC.y, C.zBack + dz);
256	    zones.chamber.add(ring);
257	  }
258	  // front wall with the round door
259	  const doorCenterC = new THREE.Vector3(C.center.x, WORLD.platform.topY + 7.0, C.zDoor);
260	  const cf = new THREE.Shape();
261	  cf.absarc(C.center.x, C.center.y, C.radius, 0, Math.PI * 2, false);
262	  const dHole = new THREE.Path();
263	  dHole.absarc(doorCenterC.x, doorCenterC.y, C.doorRadius, 0, Math.PI * 2, true);
264	  cf.holes.push(dHole);
265	  const cfGeo = new THREE.ShapeGeometry(cf, 64);
266	  cfGeo.translate(0, 0, C.zDoor);
267	  zones.chamber.add(new THREE.Mesh(cfGeo, perforatedMetal({ color: '#cf45dc', slot: 1, repeatU: 12, repeatV: 12, holeSize: 0.4, side: THREE.DoubleSide })));
268	  const doorFrame = new THREE.Mesh(new THREE.TorusGeometry(C.doorRadius + 0.55, 0.85, 24, 120), chromeMat);
269	  doorFrame.position.copy(doorCenterC).add(new THREE.Vector3(0, 0, 0.3));
270	  zones.chamber.add(doorFrame);
271	  for (const [rr, tt] of [[C.doorRadius + 2.0, 0.55], [C.doorRadius + 3.1, 0.3]] as const) {
272	    const ring = new THREE.Mesh(new THREE.TorusGeometry(rr, tt, 20, 120), goldMat);
273	    ring.position.copy(doorCenterC).add(new THREE.Vector3(0, 0, 0.5));
274	    zones.chamber.add(ring);
275	  }
276	  // door C (hinge on the right seen from inside = +X), swings outward (-Z)
277	  const doorC = new THREE.Group();
278	  doorC.name = 'doorC_pivot';
279	  doorC.position.set(doorCenterC.x + C.doorRadius + 0.9, doorCenterC.y, C.zDoor - 0.6);
280	  const doorCInner = new THREE.Group();
281	  doorCInner.position.set(-(C.doorRadius + 0.9), 0, 0);
282	  doorCInner.add(new THREE.Mesh(new THREE.TorusGeometry(C.doorRadius + 0.35, 0.75, 22, 100), chromeMat));
283	  doorCInner.add(new THREE.Mesh(new THREE.CircleGeometry(C.doorRadius + 0.2, 64), glass('#e6efff', 0.12)));
284	  const handle = new THREE.Mesh(new RoundedBoxGeometry(1.0, 2.6, 0.8, 3, 0.3), chromeMat);
285	  handle.position.set(-(C.doorRadius + 0.6), 0, -0.4);
286	  doorCInner.add(handle);
287	  doorC.add(doorCInner);
288	  const hinge = new THREE.Mesh(new RoundedBoxGeometry(1.2, 3.2, 1.2, 3, 0.3), chromeMat);
289	  hinge.position.set(doorCenterC.x + C.doorRadius + 0.9, doorCenterC.y + 2.4, C.zDoor - 0.2);
290	  const hinge2 = hinge.clone();
291	  hinge2.position.y -= 4.8;
292	  zones.chamber.add(doorC, hinge, hinge2);
293	  // laundry room C (beyond the door, toward -Z)
294	  const roomC = buildLaundryRoom({ floorDrop: 14.25, palette: 'soft', foldingTable: true });
295	  const anchorC = new THREE.Group();
296	  anchorC.position.set(doorCenterC.x, doorCenterC.y, C.zDoor - 1.0);
297	  anchorC.rotation.y = Math.PI;
298	  anchorC.add(roomC.group);
299	  zones.chamber.add(anchorC);
300	  // platform
301	  const P = WORLD.platform;
302	  const platTopMat = perforatedMetal({ color: '#d556df', emissive: '#a02cb8', emissiveIntensity: 0.3, slot: 0, repeatU: 70, repeatV: 9, holeSize: 0.42, side: THREE.DoubleSide, metalness: 0.8 });
303	  const platTop = new THREE.Mesh(new THREE.CylinderGeometry(P.radius, P.radius, 0.35, 72, 1, false), platTopMat);
304	  platTop.position.set(P.center.x, P.topY - 0.18, P.center.z);
305	  zones.chamber.add(platTop);
306	  const platRim = new THREE.Mesh(new THREE.TorusGeometry(P.radius, 0.28, 14, 96), goldMat);
307	  platRim.rotation.x = Math.PI / 2;
308	  platRim.position.set(P.center.x, P.topY - 0.15, P.center.z);
309	  zones.chamber.add(platRim);
310	  for (let i = 0; i < 4; i++) {
311	    const a = Math.PI / 4 + (i * Math.PI) / 2;
312	    const top = new THREE.Vector3(P.center.x + Math.cos(a) * P.radius * 0.72, P.topY - 0.3, P.center.z + Math.sin(a) * P.radius * 0.72);
313	    const bot = new THREE.Vector3(P.center.x + Math.cos(a) * P.radius * 0.95, C.center.y - Math.sqrt(C.radius ** 2 - (Math.cos(a) * P.radius * 0.95) ** 2) + 0.2, P.center.z + Math.sin(a) * P.radius * 0.95);
