8	export interface PerforatedOptions {
9	  /** base metal colour */
10	  color?: THREE.ColorRepresentation;
11	  /** colour of the hole interiors */
12	  holeColor?: THREE.ColorRepresentation;
13	  /** 0 = round holes (drum), 1 = slots elongated along u (tunnel rings) */
14	  slot?: number;
15	  /** pattern repeats: holes around u (per 0..1) and per uv-unit along v */
16	  repeatU?: number;
17	  repeatV?: number;
18	  /** hole size relative to its cell (0..1) */
19	  holeSize?: number;
20	  emissive?: THREE.ColorRepresentation;
21	  emissiveIntensity?: number;
22	  metalness?: number;
23	  roughness?: number;
24	  side?: THREE.Side;
25	  /** bright stripe highlights running along v (tunnel light streaks) */
26	  streaks?: number;
27	  /**
28	   * Washer-tube upgrade (05–07): pressed-metal corrugation + bevelled slot lips perturb the normal so
29	   * the glossy metal catches light around every slot (refs 05–07). Height amplitudes in world units.
30	   */
31	  relief?: { corrugation: number; bevel: number; bevelWidth?: number };
32	  /** emissive glow colour hugging every hole edge (refs: hot-pink glowing slot outlines) */
33	  rimColor?: THREE.ColorRepresentation;
34	  rimStrength?: number;
35	  /** warm "light at the end of the tunnel": emissive that grows with view distance */
36	  farGlow?: FarGlow;
37	  /** dedicated reflection environment (e.g. washerTubeEnv()) instead of scene.environment */
38	  envMap?: THREE.Texture | null;
39	  envMapIntensity?: number;
40	}
41	
42	export interface FarGlow {
43	  color: THREE.ColorRepresentation; near: number; far: number; strength: number;
44	  /** optional mid-distance tint of the metal colour (refs: walls turn violet deeper in the tunnel) */
45	  mid?: { color: THREE.ColorRepresentation; near: number; far: number; amount: number };
46	}
47	
48	/** GLSL for the distance glow, shared by the tube wall, rings and lids */
49	const FAR_GLOW_PARS = `uniform vec3 uFarGlowColor; uniform vec3 uFarGlowRange; uniform vec3 uMidTint; uniform vec3 uMidRange;
50	float farGlowK(){ return uFarGlowRange.z * smoothstep(uFarGlowRange.x, uFarGlowRange.y, length(vViewPosition)); }
51	float midTintK(){ return uMidRange.z * smoothstep(uMidRange.x, uMidRange.y, length(vViewPosition)); }`;
52	/** `solid` = 0 inside perforation holes (they stay dark), 1 on metal */
53	const FAR_GLOW_APPLY = (solid = '1.0') => `{ float sol = ${solid}; float mt = midTintK() * sol; diffuseColor.rgb = mix(diffuseColor.rgb, uMidTint, mt); totalEmissiveRadiance *= 1.0 - mt * 0.5;
54	  float fg = farGlowK(); diffuseColor.rgb = mix(diffuseColor.rgb, uFarGlowColor, min(1.0, fg * 0.5) * sol); totalEmissiveRadiance += uFarGlowColor * fg * mix(0.35, 1.0, sol); }`;
55	
56	function farGlowUniforms(g: FarGlow) {
57	  return {
58	    uFarGlowColor: { value: new THREE.Color(g.color) },
59	    uFarGlowRange: { value: new THREE.Vector3(g.near, g.far, g.strength) },
60	    uMidTint: { value: new THREE.Color(g.mid?.color ?? '#ffffff') },
61	    uMidRange: { value: new THREE.Vector3(g.mid?.near ?? 0, g.mid?.far ?? 1, g.mid?.amount ?? 0) },
62	  };
63	}
64	
65	/**
66	 * Adds the warm distance glow to any MeshStandardMaterial (rings, lids). The far end of the tube melts
67	 * into a bright warm vanishing point like refs 05/07 without adding scene lights (mobile-friendly).
68	 */
69	export function withFarGlow<T extends THREE.MeshStandardMaterial>(mat: T, g: FarGlow, key: string): T {
70	  const uniforms = farGlowUniforms(g);
71	  const prev = mat.onBeforeCompile;
72	  mat.onBeforeCompile = (shader, r) => {
73	    prev.call(mat, shader, r);
74	    Object.assign(shader.uniforms, uniforms);
75	    shader.fragmentShader = shader.fragmentShader
76	      .replace('#include <common>', '#include <common>\n' + FAR_GLOW_PARS)
77	      .replace(
78	        '#include <emissivemap_fragment>',
79	        `#include <emissivemap_fragment>
80	${FAR_GLOW_APPLY()}`,
81	      );
82	  };
83	  const prevKey = mat.customProgramCacheKey.bind(mat);
84	  mat.customProgramCacheKey = () => prevKey() + '|fg-' + key;
85	  mat.userData.farGlow = uniforms;
86	  return mat;
87	}
