89	export function perforatedMetal(o: PerforatedOptions = {}): THREE.MeshStandardMaterial {
90	  const mat = new THREE.MeshStandardMaterial({
91	    color: o.color ?? '#d13fd6',
92	    metalness: o.metalness ?? 0.72,
93	    roughness: o.roughness ?? 0.26,
94	    emissive: new THREE.Color(o.emissive ?? '#9a1fa8'),
95	    emissiveIntensity: o.emissiveIntensity ?? 0.26,
96	    side: o.side ?? THREE.BackSide,
97	    envMapIntensity: o.envMapIntensity ?? 1.0,
98	  });
99	  if (o.envMap) mat.envMap = o.envMap;
100	  const relief = o.relief;
101	  const uniforms = {
102	    uHoleColor: { value: new THREE.Color(o.holeColor ?? '#2b0640') },
103	    uSlot: { value: o.slot ?? 1 },
104	    uRepeat: { value: new THREE.Vector2(o.repeatU ?? 64, o.repeatV ?? 1.2) },
105	    uHoleSize: { value: o.holeSize ?? 0.42 },
106	    uStreaks: { value: o.streaks ?? 0.35 },
107	    uRelief: { value: new THREE.Vector3(relief?.corrugation ?? 0, relief?.bevel ?? 0, relief?.bevelWidth ?? 0.09) },
108	    uRimColor: { value: new THREE.Color(o.rimColor ?? '#ffd1ff') },
109	    uRimStrength: { value: o.rimStrength ?? 0.55 },
110	    ...(o.farGlow ? farGlowUniforms(o.farGlow) : {}),
111	  };
112	  const defines: Record<string, string> = {};
113	  if (relief) defines.PERF_RELIEF = '';
114	  if (o.farGlow) defines.PERF_FARGLOW = '';
115	  mat.defines = defines;
116	  mat.userData.perfUniforms = uniforms;
117	  mat.onBeforeCompile = (shader) => {
118	    Object.assign(shader.uniforms, uniforms);
119	    shader.vertexShader = shader.vertexShader
120	      .replace('#include <common>', '#include <common>\nvarying vec2 vPerfUv;')
121	      .replace('#include <uv_vertex>', '#include <uv_vertex>\nvPerfUv = uv;');
122	    shader.fragmentShader = shader.fragmentShader
123	      .replace(
124	        '#include <common>',
125	        `#include <common>
126	varying vec2 vPerfUv;
127	uniform vec3 uHoleColor; uniform float uSlot; uniform vec2 uRepeat; uniform float uHoleSize; uniform float uStreaks;
128	uniform vec3 uRelief; uniform vec3 uRimColor; uniform float uRimStrength;
129	#ifdef PERF_FARGLOW
130	${FAR_GLOW_PARS}
131	#endif
132	vec2 perfCell(vec2 uv){
133	  vec2 g = uv * uRepeat;
134	  g.x += mod(floor(g.y), 2.0) * 0.5;   // staggered rows
135	  return g;
136	}
137	// signed distance to the slot/hole (cell units, <0 inside)
138	float perfSdf(vec2 g){
139	  vec2 f = fract(g) - 0.5;
140	  vec2 hs = mix(vec2(uHoleSize*0.5), vec2(uHoleSize*0.62, uHoleSize*0.24), uSlot);
141	  vec2 q = abs(f) - hs + min(hs.x, hs.y);
142	  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - min(hs.x, hs.y);
143	}
144	float perfMask(vec2 uv, out float rim){
145	  vec2 g = perfCell(uv);
146	  vec2 f = fract(g) - 0.5;
147	  float d = perfSdf(g);
148	  float aa = fwidth(d) * 1.2 + 1e-4;
149	  rim = smoothstep(0.06, 0.0, abs(d - 0.02)) * step(0.0, f.y);  // light catching the lower lip
150	  return 1.0 - smoothstep(-aa, aa, d); // 1 inside hole
151	}
152	#ifdef PERF_RELIEF
153	// pressed-metal relief (world units): shallow grooves along each slot row, bevelled lips into every slot
154	float perfHeight(vec2 g){
155	  float fy = fract(g.y) - 0.5;
156	  float d = perfSdf(g);
157	  return -cos(6.2831853 * fy) * uRelief.x + (smoothstep(0.0, uRelief.z, d) - 1.0) * uRelief.y;
158	}
159	#endif`,
160	      )
161	      .replace(
162	        '#include <color_fragment>',
163	        `#include <color_fragment>
164	float perfRim; float perfHole = perfMask(vPerfUv, perfRim);
165	float streak = pow(0.5 + 0.5 * sin(vPerfUv.x * 6.2831 * 9.0 + 1.3), 18.0) * uStreaks;
166	diffuseColor.rgb = mix(diffuseColor.rgb * (1.0 + streak), uHoleColor, perfHole);`,
167	      )
168	      .replace(
169	        '#include <normal_fragment_maps>',
170	        `#include <normal_fragment_maps>
171	#ifdef PERF_RELIEF
172	{
173	  // analytic relief gradient in uv space → view space via the screen-derivative cotangent frame
174	  vec2 g = perfCell(vPerfUv);
175	  float e = 0.015;
176	  float h0 = perfHeight(g);
177	  vec2 dHdg = vec2(perfHeight(g + vec2(e, 0.0)) - h0, perfHeight(g + vec2(0.0, e)) - h0) / e;
178	  vec2 dHduv = dHdg * uRepeat;
179	  vec3 dp1 = dFdx(-vViewPosition), dp2 = dFdy(-vViewPosition);
180	  vec2 duv1 = dFdx(vPerfUv), duv2 = dFdy(vPerfUv);
181	  vec3 dp2perp = cross(dp2, normal), dp1perp = cross(normal, dp1);
182	  float det = dot(dp1, dp2perp);
183	  if (abs(det) > 1e-12) {
184	    vec3 gradU = (dp2perp * duv1.x + dp1perp * duv2.x) / det;
185	    vec3 gradV = (dp2perp * duv1.y + dp1perp * duv2.y) / det;
186	    // fade the relief out where the pattern gets sub-pixel (prevents sparkle in the distance)
187	    float px = max(length(fwidth(g)), 1e-4);
188	    float lod = 1.0 - smoothstep(0.18, 0.45, px);
189	    normal = normalize(normal - (dHduv.x * gradU + dHduv.y * gradV) * lod);
190	  }
191	}
192	#endif`,
193	      )
194	      .replace(
195	        '#include <metalnessmap_fragment>',
196	        `#include <metalnessmap_fragment>
197	metalnessFactor *= (1.0 - perfHole);`,
198	      )
199	      .replace(
200	        '#include <roughnessmap_fragment>',
201	        `#include <roughnessmap_fragment>
202	roughnessFactor = mix(roughnessFactor, 0.9, perfHole);`,
203	      )
204	      .replace(
205	        '#include <emissivemap_fragment>',
206	        `#include <emissivemap_fragment>
207	totalEmissiveRadiance = totalEmissiveRadiance * (1.0 - perfHole) + uRimColor * perfRim * uRimStrength * (1.0 - perfHole) + vec3(1.0,0.9,1.0) * streak * 0.6;
208	#ifdef PERF_FARGLOW
209	${FAR_GLOW_APPLY('1.0 - perfHole')}
210	#endif`,
211	      );
212	  };
213	  mat.customProgramCacheKey = () => 'perf-v2' + (relief ? '-r' : '') + (o.farGlow ? '-g' : '');
214	  return mat;
215	}
