217	/**
218	 * Reflection environment for the washer tubes (05–07): an HDR cube of hot-pink / magenta / violet with
219	 * pink-white strip lights around the tube and a warm gold-white glow down the tunnel (-Z), so the glossy
220	 * walls read rich saturated magenta (the shared candy studio has a cyan panel that turned them sky-blue).
221	 * Built from half-float DataTextures; three converts it to PMREM on first use (no renderer needed here).
222	 */
223	const tubeEnvs: Partial<Record<'wall' | 'gold', THREE.CubeTexture>> = {};
224	/** variant 'gold': same tunnel lighting seen by polished gold (warm-white strips, amber base) so rings and
225	 *  lids read clean orange-gold with yellow-white highlights instead of salmon (gold × magenta). */
226	export function washerTubeEnv(variant: 'wall' | 'gold' = 'wall'): THREE.CubeTexture {
227	  const cached = tubeEnvs[variant];
228	  if (cached) return cached;
229	  const isGold = variant === 'gold';
230	  const N = 128;
231	  const dir = new THREE.Vector3();
232	  const col = new THREE.Color();
233	  const faces: THREE.DataTexture[] = [];
234	  // cube face orientation (same convention as WebGL cube maps)
235	  const faceDir = (f: number, a: number, b: number) => {
236	    switch (f) {
237	      case 0: return dir.set(1, -b, -a);
238	      case 1: return dir.set(-1, -b, a);
239	      case 2: return dir.set(a, 1, b);
240	      case 3: return dir.set(a, -1, -b);
241	      case 4: return dir.set(a, -b, 1);
242	      default: return dir.set(-a, -b, -1);
243	    }
244	  };
245	  const radiance = (d: THREE.Vector3, out: THREE.Color) => {
246	    const ang = Math.atan2(d.y, d.x); // angle around the tunnel axis (Z)
247	    const up = d.y;
248	    // base: deep hot magenta above, violet toward the floor (kept dark so the strips give contrast)
249	    if (isGold) out.setRGB(0.5, 0.24, 0.12).lerp(new THREE.Color(0.2, 0.07, 0.1), THREE.MathUtils.smoothstep(-up, -0.2, 0.9));
250	    else out.setRGB(0.4, 0.03, 0.3).lerp(new THREE.Color(0.16, 0.05, 0.5), THREE.MathUtils.smoothstep(-up, -0.2, 0.9));
251	    // pink-white strip lights running along the tunnel at fixed angles around it (8, uneven strength)
252	    for (let i = 0; i < 8; i++) {
253	      const a0 = 0.2 + (i * Math.PI) / 4;
254	      const dA = Math.abs(Math.atan2(Math.sin(ang - a0), Math.cos(ang - a0)));
255	      // the strips run the whole length of the tunnel, so they converge at ±Z like meridians: rings and
256	      // grazing walls pick them up as regularly spaced highlight spots/streaks (refs 05–07)
257	      const k = Math.exp(-(dA * dA) / (isGold ? 0.0025 : 0.005)) * (isGold ? 1 : 1 - Math.abs(d.z) * 0.35) * (i % 2 ? 0.7 : 1.15);
258	      if (isGold) { out.r += 7.0 * k; out.g += 5.6 * k; out.b += 3.6 * k; } else { out.r += 3.4 * k; out.g += 1.7 * k; out.b += 3.1 * k; }
259	    }
260	    // warm light at the very end of the tunnel (-Z), violet haze around it, softer pink glow behind (+Z)
261	    const ahead = Math.max(0, -d.z);
262	    const hot = Math.pow(ahead, 24), wide = Math.pow(ahead, 3);
263	    out.r += 3.6 * hot; out.g += 2.9 * hot; out.b += 1.4 * hot;
264	    if (isGold) { out.r += 0.6 * wide; out.g += 0.4 * wide; out.b += 0.15 * wide; } else { out.r += 0.18 * wide; out.g += 0.06 * wide; out.b += 0.5 * wide; }
265	    const back = Math.pow(Math.max(0, d.z), 4);
266	    out.r += 0.9 * back; out.g += 0.25 * back; out.b += 0.8 * back;
267	    return out;
268	  };
269	  for (let f = 0; f < 6; f++) {
270	    const data = new Uint16Array(N * N * 4);
271	    for (let y = 0; y < N; y++) {
272	      for (let x = 0; x < N; x++) {
273	        const a = ((x + 0.5) / N) * 2 - 1, b = ((y + 0.5) / N) * 2 - 1;
274	        radiance(faceDir(f, a, b).normalize(), col);
275	        const i = (y * N + x) * 4;
276	        data[i] = THREE.DataUtils.toHalfFloat(col.r);
277	        data[i + 1] = THREE.DataUtils.toHalfFloat(col.g);
278	        data[i + 2] = THREE.DataUtils.toHalfFloat(col.b);
279	        data[i + 3] = THREE.DataUtils.toHalfFloat(1);
280	      }
281	    }
282	    const t = new THREE.DataTexture(data, N, N, THREE.RGBAFormat, THREE.HalfFloatType);
283	    t.colorSpace = THREE.LinearSRGBColorSpace;
284	    t.needsUpdate = true;
285	    faces.push(t);
286	  }
287	  const cube = new THREE.CubeTexture(faces as unknown as HTMLImageElement[]);
288	  cube.type = THREE.HalfFloatType;
289	  cube.format = THREE.RGBAFormat;
290	  cube.colorSpace = THREE.LinearSRGBColorSpace;
291	  cube.minFilter = THREE.LinearFilter;
292	  cube.magFilter = THREE.LinearFilter;
293	  cube.generateMipmaps = false;
294	  cube.needsUpdate = true;
295	  tubeEnvs[variant] = cube;
296	  return cube;
297	}
