211	/**
212	 * Washer-tube ring collar (refs 05–07): a thick flanged gold band hugging the wall with a broad flat
213	 * inner face, bevelled shoulders and a raised centre lip — it catches crisp specular lines instead of
214	 * reading as a round pipe/helix. Lathe around local Z; radial values are fractions of the tube radius,
215	 * axial values are world units (the instance scales z by 1).
216	 */
217	export function collarGeometry(depth = 0.062, lip = 0.016, width = 1.0, segments = 80): THREE.BufferGeometry {
218	  const w = width / 2;
219	  const d = depth, L = depth + lip;
220	  // traversed from +z to -z so LatheGeometry's faces/normals point INWARD (toward the tunnel axis)
221	  const prof: [number, number][] = [
222	    [1.03, w], [1 - d * 0.3, w], [1 - d * 0.78, w * 0.96], [1 - d, w * 0.84],
223	    [1 - d, w * 0.36], [1 - d - lip * 0.55, w * 0.27], [1 - L, w * 0.16], [1 - L, -w * 0.16],
224	    [1 - d - lip * 0.55, -w * 0.27], [1 - d, -w * 0.36], [1 - d, -w * 0.84], [1 - d * 0.78, -w * 0.96],
225	    [1 - d * 0.3, -w], [1.03, -w],
226	  ];
227	  const g = new THREE.LatheGeometry(prof.map(([x, y]) => new THREE.Vector2(x, y)), segments);
228	  g.rotateX(Math.PI / 2); // lathe axis Y → tube axis Z
229	  return g;
230	}
231	
232	/** Instanced thick gold ring ribs placed perpendicular to the tube every `spacing` units. */
233	export function buildRings(
234	  path: TubePath,
235	  s0: number,
236	  s1: number,
237	  spacing: number,
238	  material: THREE.Material,
239	  opts: { tube?: number; double?: boolean; inset?: number; extra?: number; collar?: { depth?: number; lip?: number; width?: number; segments?: number } } = {},
240	): THREE.InstancedMesh {
241	  const tube = opts.tube ?? 0.075;
242	  const collar = opts.collar;
243	  const geo = collar ? collarGeometry(collar.depth, collar.lip, collar.width, collar.segments) : new THREE.TorusGeometry(1, tube, 14, 72);
244	  const n = Math.max(1, Math.floor((s1 - s0) / spacing) + 1) * (opts.double ? 2 : 1);
245	  const mesh = new THREE.InstancedMesh(geo, material, n);
246	  const m = new THREE.Matrix4();
247	  const q = new THREE.Quaternion();
248	  const basis = new THREE.Matrix4();
249	  const c = new THREE.Vector3();
250	  let k = 0;
251	  for (let s = s0; s <= s1 + 1e-6 && k < n; s += spacing) {
252	    for (let dbl = 0; dbl < (opts.double ? 2 : 1); dbl++) {
253	      const ss = s + dbl * spacing * 0.16;
254	      const f = path.frame(ss);
255	      const r = path.radius(ss) - (opts.inset ?? 0.05) + (opts.extra ?? 0);
256	      c.copy(f.pos).addScaledVector(f.up, path.radius(ss) - path.depth(ss));
257	      basis.makeBasis(f.right, f.up, f.tan);
258	      q.setFromRotationMatrix(basis);
259	      const sc = dbl ? r * 0.985 : r;
260	      // a collar keeps its axial width in world units; a torus scales uniformly
261	      m.compose(c, q, new THREE.Vector3(sc, sc, collar ? 1 : sc * (dbl ? 0.6 : 1)));
262	      mesh.setMatrixAt(k++, m);
263	    }
264	  }
265	  mesh.count = k;
266	  mesh.instanceMatrix.needsUpdate = true;
267	  mesh.frustumCulled = false;
268	  return mesh;
269	}
