271	/**
272	 * Washer wall lids (refs 05–07): stubby polished gold caps — a rounded puck with a raised rim lip and a
273	 * slightly recessed face — hanging on BOTH upper side walls in pairs, one pair per ring bay, like spray
274	 * caps aimed down at the stream: the face looks down (+ a little inward), the puck is stretched along the
275	 * tunnel and partly sunk into the wall, so the rider sees a bright banded rim on top and the darker face
276	 * below (the reference's "D" silhouette). One instanced mesh (1 draw call).
277	 */
278	export function buildWallLids(
279	  path: TubePath,
280	  s0: number,
281	  s1: number,
282	  spacing: number,
283	  material: THREE.Material,
284	  opts: { angleDeg?: number; size?: number; height?: number; stretch?: number; down?: number; sink?: number; stagger?: number } = {},
285	): THREE.InstancedMesh {
286	  const a = 1, h = opts.height ?? 0.5;
287	  // closed cap: back disc, short side band, rounded shoulder, raised rim lip, slightly recessed face
288	  const prof: [number, number][] = [
289	    [0, -0.12], [a * 1.03, -0.12], [a * 1.03, 0], [a, 0.06], [a, h - 0.12], [a * 0.95, h - 0.02], [a * 0.88, h],
290	    [a * 0.8, h], [a * 0.76, h - 0.05], [a * 0.7, h - 0.08], [0, h - 0.08],
291	  ];
292	  const geo = new THREE.LatheGeometry(prof.map(([x, y]) => new THREE.Vector2(x, y)), 40);
293	  const n = (Math.floor((s1 - s0) / spacing) + 1) * 2;
294	  const mesh = new THREE.InstancedMesh(geo, material, n);
295	  const size = opts.size ?? 1.25;
296	  const ang = THREE.MathUtils.degToRad(opts.angleDeg ?? 14);
297	  const down = opts.down ?? 0.75;
298	  const c = new THREE.Vector3(), dir = new THREE.Vector3(), Y = new THREE.Vector3(), X = new THREE.Vector3(), Z = new THREE.Vector3();
299	  const basis = new THREE.Matrix4(), m = new THREE.Matrix4(), q = new THREE.Quaternion();
300	  let k = 0;
301	  for (let s = s0; s <= s1 + 1e-6; s += spacing) {
302	    for (const side of [1, -1]) {
303	      const ss = s + (side > 0 ? 0 : (opts.stagger ?? 0) * spacing);
304	      if (ss > s1) continue;
305	      const f = path.frame(ss);
306	      const r = path.radius(ss);
307	      tubeCenterAt(path, ss, c);
308	      dir.copy(f.right).multiplyScalar(Math.cos(ang) * side).addScaledVector(f.up, Math.sin(ang)).normalize();
309	      const sz = size * (r / 7.6);
310	      // face normal: blend of inward (−dir) and straight down (−up)
311	      Y.copy(dir).negate().multiplyScalar(1 - down).addScaledVector(f.up, -down).normalize();
312	      X.copy(f.tan).addScaledVector(Y, -f.tan.dot(Y)).normalize(); // stretched along the tunnel
313	      Z.crossVectors(X, Y).normalize();
314	      basis.makeBasis(X, Y, Z);
315	      q.setFromRotationMatrix(basis);
316	      // centre just inside the wall: `sink` of the cap's radius stays buried in the metal
317	      const p = c.clone().addScaledVector(dir, r - sz * 0.9 * (1 - (opts.sink ?? 0.35)));
318	      m.compose(p, q, new THREE.Vector3(sz * (opts.stretch ?? 1.45), sz, sz * 0.9));
319	      mesh.setMatrixAt(k++, m);
320	    }
321	  }
322	  mesh.count = k;
323	  mesh.instanceMatrix.needsUpdate = true;
324	  mesh.frustumCulled = false;
325	  return mesh;
326	}
