328	/** Half-dome wall "lids"/spray heads mounted on the upper tube walls (refs 05–07). */
329	export function buildNozzles(
330	  path: TubePath,
331	  s0: number,
332	  s1: number,
333	  spacing: number,
334	  domeMat: THREE.Material,
335	  rimMat: THREE.Material,
336	  opts: { angleDeg?: number; size?: number } = {},
337	): THREE.Group {
338	  const group = new THREE.Group();
339	  const size = opts.size ?? 1.6;
340	  const dome = new THREE.SphereGeometry(1, 28, 12, 0, Math.PI * 2, 0, Math.PI / 2);
341	  dome.scale(1.25, 0.55, 0.85);
342	  const rim = new THREE.TorusGeometry(1, 0.1, 10, 40);
343	  rim.rotateX(Math.PI / 2);
344	  rim.scale(1.25, 1, 0.85);
345	  const nDomes = Math.floor((s1 - s0) / spacing) + 1;
346	  const imDome = new THREE.InstancedMesh(dome, domeMat, nDomes);
347	  const imRim = new THREE.InstancedMesh(rim, rimMat, nDomes);
348	  const m = new THREE.Matrix4();
349	  const basis = new THREE.Matrix4();
350	  const q = new THREE.Quaternion();
351	  const c = new THREE.Vector3();
352	  const dir = new THREE.Vector3();
353	  let k = 0;
354	  for (let s = s0; s <= s1 && k < nDomes; s += spacing, k++) {
355	    const f = path.frame(s);
356	    const r = path.radius(s);
357	    const side = k % 2 === 0 ? 1 : -1;
358	    const ang = THREE.MathUtils.degToRad(opts.angleDeg ?? 32);
359	    tubeCenterAt(path, s, c);
360	    dir.copy(f.right).multiplyScalar(Math.cos(ang) * side).addScaledVector(f.up, Math.sin(ang)).normalize();
361	    const p = c.clone().addScaledVector(dir, r * 0.985);
362	    const inward = dir.clone().negate();
363	    const xAxis = new THREE.Vector3().crossVectors(inward, f.tan).normalize();
364	    const zAxis = new THREE.Vector3().crossVectors(xAxis, inward).normalize();
365	    basis.makeBasis(xAxis, inward, zAxis);
366	    q.setFromRotationMatrix(basis);
367	    m.compose(p, q, new THREE.Vector3(size, size, size));
368	    imDome.setMatrixAt(k, m);
369	    imRim.setMatrixAt(k, m);
370	  }
371	  imDome.count = imRim.count = k;
372	  imDome.frustumCulled = imRim.frustumCulled = false;
373	  group.add(imDome, imRim);
374	  return group;
375	}
